-- ----------------------------------------------------------------------------
-- Kaynak: "ALİ KEMAL SEZGİN FUTBOL TURNUVASI.xls" (resmî fikstür, 2025-2026)
-- Demo (seed) verilerini tamamen siler ve gerçek verileri yükler:
--   * 1 turnuva  : 2025-2026 Ali Kemal Sezgin Futbol Turnuvası
--   * 1 saha     : Yığılca 1 Nolu Saha
--   * 5 grup     : A-D 5'er takım, E grubu 6 takım (toplam 26 takım)
--   * 55 grup maçı: 17 Temmuz - 3 Ağustos 2026 (hepsi planlandı durumunda)
-- Eleme aşaması fikstürde YOK: 04.08.2026'da kura çekilecek
-- (grup birincileri seri başı). Eleme maçları panelden oluşturulacak.
-- Not: Excel'deki 11. maçta "ATATÜRK MAAHALLESİ" yazımı "Atatürk Mahallesi"
--      takımı olarak düzeltildi.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- DEMO VERİLERİNİ TEMİZLE
-- Sıra önemli: tournament cascade'ine bırakılırsa oyuncu silinirken
-- match_events.player_id "set null" güncellemesi trg_sync_cards trigger'ını
-- tetikleyip silinmiş maça kart yazmaya çalışıyor (FK hatası). Önce olayları
-- silince trigger yalnızca temizlik yapar ve sorun oluşmaz.
-- ----------------------------------------------------------------------------
delete from public.match_events;
delete from public.cards;
delete from public.suspensions;
delete from public.lineups;
delete from public.matches;
delete from public.players;
delete from public.teams;
delete from public.groups;
delete from public.venues;
delete from public.announcements;
delete from public.settings;
delete from public.tournaments;

